try:
    result = pd.Series([2, 3], dtype=object).astype('m8[s]')
    probe("pd.Series([2, 3], dtype=object).astype('m8[s]')", result.tolist())
except Exception as e:
    probe("pd.Series([2, 3], dtype=object).astype('m8[s]')", "__error__: " + type(e).__name__ + ": " + str(e))

